// Using Redisson, the standard Java client for Redlock
RLock lock = redisson.getLock("my-resource-key");
try {
    // Wait 10s, lease for 30s to prevent deadlocks if the node crashes
    if (lock.tryLock(10, 30, TimeUnit.SECONDS)) {
        try {
            // Perform critical section logic
        } finally {
            lock.unlock();
        }
    }
} catch (InterruptedException e) {
    Thread.currentThread().interrupt();
}
